import { createPlayerError } from "../../core/errors.js";

/** Mini-player sizing options. */
export interface MiniPlayerOptions {
  readonly width?: number;
  readonly height?: number;
}

/** Returns true when the Picture-in-Picture mini-player is available. */
export function canUseMiniPlayer(): boolean {
  return (
    typeof document !== "undefined" &&
    "pictureInPictureEnabled" in document &&
    document.pictureInPictureEnabled === true
  );
}

/** Enters the browser mini-player. */
export async function enterMiniPlayer(
  media: HTMLVideoElement,
  options: MiniPlayerOptions = {},
): Promise<void> {
  if (!canUseMiniPlayer() || typeof media.requestPictureInPicture !== "function") {
    throw createPlayerError("The mini-player is not supported in this environment.", {
      code: "unsupported-environment",
    });
  }

  if (options.width !== undefined) {
    media.style.width = `${options.width}px`;
  }

  if (options.height !== undefined) {
    media.style.height = `${options.height}px`;
  }

  await media.requestPictureInPicture();
}

/** Exits the browser mini-player. */
export async function exitMiniPlayer(): Promise<void> {
  if (typeof document === "undefined" || typeof document.exitPictureInPicture !== "function") {
    throw createPlayerError("The mini-player is not supported in this environment.", {
      code: "unsupported-environment",
    });
  }

  if (document.pictureInPictureElement !== null) {
    await document.exitPictureInPicture();
  }
}
